// r23 s04 copy of qa/match/04/r22/tools/audit_pinned.mjs: identical except the screenshot + page-ready timeouts (600 s; the machine is shared).
// r22 S04 copy of tools/lead21/audit_screen.mjs with ONE QA-only change: performance.now() is pinned to 10 000 ms while each
// shot is stepped and drawn, so the Screen 04 river shader (src/world/match04m4.ts reads the wall clock, pre-existing since
// 34cb494) shows the same water phase in every run -> BEFORE / NEW differ only by the switch under test. No game code changes.
// Round 21 lead audit (read-only): one playable screen of the REAL game at start / early / middle / late / end and hard
// left / right, deterministic (fixed sim steps, frozen shader clock, one frame rendered per shot, no real-time steps).
// Run from the worktree whose build you want to see (vite serves the current directory):
//   cd <worktree> && node /home/user/rainbow-/tools/lead21/audit_screen.mjs <outDir> <stage 04..08> "<query>"
// Shots are fractions of the stage from its checkpoint to its end; env AUDIT_SHOTS='[["name",frac,steer],...]' overrides.
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, STAGE, Q] = process.argv.slice(2);
const SHOTS = process.env.AUDIT_SHOTS ? JSON.parse(process.env.AUDIT_SHOTS)
  : [['a_start', 0, null], ['b_early', 0.12, null], ['c_middle', 0.35, null], ['d_late', 0.6, null], ['e_end', 0.85, null],
     ['f_hard_left', 0.35, -1], ['g_hard_right', 0.35, 1]];
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.AUDIT_PORT ?? 5290));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  page.on('console', (m) => { if (m.type() === 'error' && /Shader|WebGL|rror/.test(m.text())) console.error('console', m.text().slice(0, 160)); });
  await page.goto(`${vite.url}/?qa=1&dpr=1&${Q}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 600000 });
  for (const [name, frac, steer] of SHOTS) {
    const st = await page.evaluate(async ([stage, frac, steer]) => {
      const r = window.__rainbow;
      const _pn = performance.now; performance.now = () => 10000;
      r.goto(stage);
      const s0 = r.state().s, s1 = r.course.stage(stage).s1;
      const tS = s0 + frac * (s1 - s0);
      r.setSteer(steer);
      let k = 0; while (r.state().s < tS && k < 6000) { r.step(1); k++; }
      r.setSteer(null);
      r.freezeAt(10);
      r.drawList();
      await new Promise((res) => requestAnimationFrame(() => res()));
#!/usr/bin/env bash
# render_slot.sh — run one heavy render (Playwright / SwiftShader / Blender / ffmpeg) while holding one of N machine-wide
# render slots, so the four specialist workers on this 4-CPU container take turns instead of overloading it
# (round 24 ran at load ~30 with repeated Playwright timeouts).
#   usage:  bash /home/user/rainbow-/tools/lead25/render_slot.sh <command> [args...]
#   N = $RENDER_SLOTS (default 2). Waits (polling every 5 s) until a slot is free; prints the wait time on stderr.
#   The exit code is the command's. Slots are flock(1) locks under /tmp, released automatically if the process dies.
#   Status:  bash /home/user/rainbow-/tools/lead25/render_slot.sh --status
N=${RENDER_SLOTS:-2}
if [ "${1:-}" = "--status" ]; then
  for i in $(seq 1 "$N"); do
    if flock -n "/tmp/rainbow-render-slot$i.lock" true 2>/dev/null; then echo "slot $i free"; else echo "slot $i busy"; fi
  done
  exit 0
fi
[ $# -gt 0 ] || { echo "usage: $0 <command> [args...]" >&2; exit 2; }
t0=$(date +%s)
while true; do
  for i in $(seq 1 "$N"); do
    exec {fd}>"/tmp/rainbow-render-slot$i.lock"
    if flock -n "$fd"; then
      w=$(( $(date +%s) - t0 )); [ "$w" -gt 0 ] && echo "[render_slot] got slot $i after ${w}s" >&2
      nice -n 5 "$@"; rc=$?
      flock -u "$fd"; exec {fd}>&-
      exit $rc
    fi
    exec {fd}>&-
  done
  sleep 5
done
